-- AgroAlerta Cañete - Esquema de referencia para crear en Supabase (SQL Editor).
-- NO se ejecuta automaticamente: el usuario crea las tablas en Supabase.
-- IMPORTANTE: las claves primarias deben ser identidad (BIGSERIAL o
-- GENERATED BY DEFAULT AS IDENTITY) porque el backend las gestiona con IDENTITY.
--
-- Tipos estandar confirmados con el usuario al no disponer del diagrama original.

CREATE TABLE IF NOT EXISTS agricultor (
    id_agricultor BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombres       VARCHAR(100) NOT NULL,
    apellidos     VARCHAR(100) NOT NULL,
    telefono      VARCHAR(20),
    dni           VARCHAR(8),
    foto_url      TEXT
);

CREATE TABLE IF NOT EXISTS parcela (
    id_parcela     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_agricultor  BIGINT NOT NULL REFERENCES agricultor (id_agricultor),
    nombre         VARCHAR(120) NOT NULL,
    area_hectareas NUMERIC(10, 2) NOT NULL CHECK (area_hectareas > 0),
    ubicacion      VARCHAR(200),
    foto_url       TEXT
);

CREATE TABLE IF NOT EXISTS cultivo (
    id_cultivo BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre      VARCHAR(100) NOT NULL,
    variedad    VARCHAR(100),
    foto_url    TEXT
);

CREATE TABLE IF NOT EXISTS campana (
    id_campana   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_parcela   BIGINT NOT NULL REFERENCES parcela (id_parcela),
    id_cultivo   BIGINT NOT NULL REFERENCES cultivo (id_cultivo),
    nombre       VARCHAR(150) NOT NULL,
    fecha_inicio DATE NOT NULL,
    fecha_fin    DATE CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);

CREATE TABLE IF NOT EXISTS riego (
    id_riego    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_campana  BIGINT NOT NULL REFERENCES campana (id_campana),
    fecha_riego DATE NOT NULL,
    cantidad_m3 NUMERIC(12, 3) NOT NULL CHECK (cantidad_m3 >= 0),
    observacion VARCHAR(300)
);

CREATE TABLE IF NOT EXISTS gasto (
    id_gasto    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_campana  BIGINT NOT NULL REFERENCES campana (id_campana),
    concepto    VARCHAR(150) NOT NULL,
    fecha_gasto DATE NOT NULL,
    monto       NUMERIC(12, 2) NOT NULL CHECK (monto >= 0)
);

CREATE TABLE IF NOT EXISTS cosecha (
    id_cosecha    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_campana    BIGINT NOT NULL REFERENCES campana (id_campana),
    fecha_cosecha DATE NOT NULL,
    cantidad_kg   NUMERIC(12, 2) NOT NULL CHECK (cantidad_kg >= 0),
    observacion   VARCHAR(300)
);

CREATE TABLE IF NOT EXISTS venta (
    id_venta     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_cosecha   BIGINT NOT NULL REFERENCES cosecha (id_cosecha),
    fecha_venta  DATE NOT NULL,
    cantidad_kg  NUMERIC(12, 2) NOT NULL CHECK (cantidad_kg >= 0),
    precio_total NUMERIC(12, 2) NOT NULL CHECK (precio_total >= 0),
    comprador    VARCHAR(150) NOT NULL
);

-- Indices sobre claves foraneas y consultas frecuentes
CREATE INDEX IF NOT EXISTS idx_parcela_agricultor ON parcela (id_agricultor);
CREATE INDEX IF NOT EXISTS idx_campana_parcela ON campana (id_parcela);
CREATE INDEX IF NOT EXISTS idx_campana_cultivo ON campana (id_cultivo);
CREATE INDEX IF NOT EXISTS idx_campana_fechas ON campana (fecha_inicio, fecha_fin);
CREATE INDEX IF NOT EXISTS idx_riego_campana ON riego (id_campana);
CREATE INDEX IF NOT EXISTS idx_gasto_campana ON gasto (id_campana);
CREATE INDEX IF NOT EXISTS idx_cosecha_campana ON cosecha (id_campana);
CREATE INDEX IF NOT EXISTS idx_venta_cosecha ON venta (id_cosecha);
CREATE INDEX IF NOT EXISTS idx_venta_fecha ON venta (fecha_venta);
